    await expect(
      projectService.createProject(free.actors.owner, {
        orgId: free.org.id,
        name: "Third",
        slug: "third",
        key: "THR",
        description: null,
        visibility: "org",
        leadId: null,
        color: "#6366f1",
        targetDate: null,
      }),
