/**
 * Batched read that keeps the order of `issueIds`. Archived rows are included,
 * because an import's result still names them after they are archived.
 */
export async function findIssuesByIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        inArray(issues.id, [...issueIds]),
      ),
    )
    .all();

  const labels = await listLabelsForIssues(orgId, issueIds);
  const byId = new Map(
    rows.map((row) => [
      row.id,
      toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
    ]),
  );

  return issueIds.flatMap((issueId) => {
    const issue = byId.get(issueId);
    return issue ? [issue] : [];
  });
}

/** Builds the shared predicate list behind `listIssues` and its count. */

