/**
 * Bulk-import persistence: the per-workspace idempotency record and the single
 * transaction that writes a whole batch or nothing.
 *
 * Must call (do not reimplement): orgPredicate, newId, toIssue, brandId, parseJsonArray
 */
import { and, eq, inArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  getDb,
  issueImports,
  issueLabels,
  issues,
  labels,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, parseJsonArray, toIssue } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue, IssuePriority, IssueStatus } from "@/types/issue";

/** What a completed import left behind, keyed by `(orgId, importKey)`. */
export interface IssueImportRecord {
  readonly importKey: string;
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
}

/** One row of a batch, with its assignee already resolved to a workspace member. */
export interface IssueImportRowWrite {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  /** Distinct label names; any that do not exist yet are created in the same write. */
  readonly labelNames: readonly string[];
}

export interface IssueImportWrite {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly importedBy: UserId;
  readonly rows: readonly IssueImportRowWrite[];
}

export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  return {
    importKey: row.importKey,
    projectId: brandId<ProjectId>(row.projectId),
    issueIds: parseJsonArray<string>(row.issueIds).map((id) =>
      brandId<IssueId>(id),
    ),
  };
}

/**
 * Inserts every row, the labels they name and the import record inside one
 * synchronous SQLite transaction. Nothing is visible unless all of it lands, and
 * the numbering is read inside the same transaction, so no other write can slip
 * a number in between.
 */
export async function writeIssueImport(
  write: IssueImportWrite,
): Promise<readonly Issue[]> {
  return getDb().transaction((tx) => {
    const stamp = toIsoTimestamp(new Date());

    const highest = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, write.orgId),
          eq(issues.projectId, write.projectId),
        ),
      )
      .get();
    const firstNumber = (highest?.value ?? 0) + 1;

    const names = [...new Set(write.rows.flatMap((row) => row.labelNames))];
    const labelIdByName = new Map<string, LabelId>();

    if (names.length > 0) {
      const existing = tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(
          and(
            orgPredicate(labels.orgId, write.orgId),
            inArray(labels.name, names),
          ),
        )
        .all();
      for (const label of existing) {
        labelIdByName.set(label.name, brandId<LabelId>(label.id));
      }
    }

    for (const name of names) {
      if (labelIdByName.has(name)) continue;
      // Default colour and no description, as a label created by name alone.
      const created = tx
        .insert(labels)
        .values({
          id: newId(),
          orgId: write.orgId,
          name,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning({ id: labels.id })
        .get();
      labelIdByName.set(name, brandId<LabelId>(created.id));
    }

    const created: Issue[] = [];

    for (const [index, row] of write.rows.entries()) {
      const issueRow = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId: write.orgId,
          projectId: write.projectId,
          number: firstNumber + index,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: write.importedBy,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      const labelIds = row.labelNames
        .map((name) => labelIdByName.get(name))
        .filter((labelId): labelId is LabelId => labelId !== undefined);

      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId: write.orgId,
              issueId: issueRow.id,
              labelId,
            })),
          )
          .run();
      }

      created.push(toIssue(issueRow, labelIds));
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: write.orgId,
        importKey: write.importKey,
        projectId: write.projectId,
        importedBy: write.importedBy,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return created;
  });
}

