/**
 * Bulk import from an uploaded file. The gates match `createIssue` (tenant
 * scope, a live project, `issue:create`, the per-project quota), with the batch
 * counted as a whole and the rate allowance charged one unit per row. Everything
 * is decided before the single transactional write, so a refusal writes nothing.
 *
 * A key this workspace has already imported returns that first result and
 * writes nothing. Its key is only recorded by a successful write, so a refused
 * upload leaves the key free. One `issues.imported` event replaces the per-issue
 * `issue.created` announcements.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const replay = await issueImportRepo.findIssueImport(
    input.orgId,
    input.importKey,
  );
  if (replay !== null) {
    return {
      importKey: replay.importKey,
      projectId: replay.projectId,
      issues: await issueRepo.findIssuesByIds(input.orgId, replay.issueIds),
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assignees = await memberRepo.findActiveMemberIdsByEmail(
    input.orgId,
    input.rows.flatMap((row) =>
      row.assigneeEmail === null ? [] : [row.assigneeEmail],
    ),
  );

  const created = await issueImportRepo.writeIssueImport({
    orgId: input.orgId,
    projectId: input.projectId,
    importKey: input.importKey,
    importedBy: actor.userId,
    rows: input.rows.map((row) => ({
