/**
 * Bulk issue import: the all-or-nothing write, replays, the batch quota and
 * rate spend, assignee and label resolution, and the single batch announcement
 * that fans out to search, usage and the audit log.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { PermissionDeniedError } from "@/lib/permissions";
import { setOrgPlan } from "@/lib/rate-limit";
import { TenantScopeError } from "@/lib/tenant";
import type { ImportIssueRowInput } from "@/schemas/issue-import";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as activityService from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function row(
  title: string,
  overrides: Partial<ImportIssueRowInput> = {},
): ImportIssueRowInput {
  return {
    title,
    description: null,
    status: "backlog",
    priority: "none",
    assigneeEmail: null,
    labels: [],
    dueAt: null,
    ...overrides,
  };
}

function batch(
  orgId: Tenant["org"]["id"],
  projectId: Tenant["project"]["id"],
  importKey: string,
  rows: readonly ImportIssueRowInput[],
) {
  return { orgId, projectId, importKey, rows };
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("importsvc");
  // Lets the batch rate allowance scale like a growth org's would.
  setOrgPlan(tenant.org.id, "growth");
  registerEventHandlers();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

describe("issues.imported batch", () => {
  it("creates every row in file order, authored by the importer, with one batch event", async () => {
    const batches = capture("issues.imported");
    const created = capture("issue.created");

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant.org.id, tenant.project.id, "first-upload-key", [
        row("First imported"),
        row("Second imported", { priority: "high", dueAt: "2030-01-02T03:04:05.000Z" }),
        row("Third imported", { description: "details" }),
      ]),
    );

    expect(result.replayed).toBe(false);
    expect(result.issues.map((issue) => issue.title)).toEqual([
      "First imported",
      "Second imported",
      "Third imported",
    ]);
    expect(result.issues[1]).toMatchObject({
      priority: "high",
      dueAt: "2030-01-02T03:04:05.000Z",
      parentId: null,
      estimate: null,
    });
    expect(result.issues[2]?.description).toBe("details");
    expect(result.issues.every((issue) => issue.authorId === tenant.userIds.member)).toBe(true);

    const numbers = result.issues.map((issue) => issue.number);
    expect(numbers[1]).toBe(numbers[0]! + 1);
    expect(numbers[2]).toBe(numbers[1]! + 1);

    expect(batches).toHaveLength(1);
    expect(batches[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      projectId: tenant.project.id,
      importKey: "first-upload-key",
      issueIds: result.issues.map((issue) => issue.id),
    });
    expect(created).toHaveLength(0);

    const next = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "After the import" }),
    );
    expect(next.number).toBe(numbers[2]! + 1);
  });

  it("returns the first result, with replayed set, when a key is uploaded again", async () => {
    const first = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant.org.id, tenant.project.id, "replay-key-001", [
        row("Original one"),
        row("Original two"),
      ]),
    );

    const batches = capture("issues.imported");
    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id);

    const replay = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant.org.id, tenant.project.id, "replay-key-001", [
        row("Rows changed entirely"),
      ]),
    );

    expect(replay.replayed).toBe(true);
    expect(replay.issues.map((issue) => issue.id)).toEqual(
      first.issues.map((issue) => issue.id),
    );
    expect(replay.issues.map((issue) => issue.title)).toEqual(["Original one", "Original two"]);
    await expect(issueRepo.countIssues(tenant.org.id, tenant.project.id)).resolves.toBe(before);
    expect(batches).toHaveLength(0);
  });

  it("treats identical rows under a different key as a new import", async () => {
    const rows = [row("Same rows, new key")];
    const first = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant.org.id, tenant.project.id, "distinct-key-aaa", rows),
    );
    const second = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant.org.id, tenant.project.id, "distinct-key-bbb", rows),
    );

    expect(second.replayed).toBe(false);
    expect(second.issues[0]?.id).not.toBe(first.issues[0]?.id);
  });

  it("refuses the whole batch past the project quota and leaves the key free", async () => {
    const quota = await createTenant("importquota", "free");
    for (let number = 1; number <= 99; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quota.org.id, quota.project.id, { title: `Seed ${number}` }),
        quota.actors.member.userId,
        number,
      );
    }

    await expect(
      issueService.importIssues(
        quota.actors.member,
        batch(quota.org.id, quota.project.id, "quota-key-001", [row("One"), row("Two")]),
      ),
    ).rejects.toThrow(/allows no more issues/);
    await expect(issueRepo.countIssues(quota.org.id, quota.project.id)).resolves.toBe(99);

    const retry = await issueService.importIssues(
      quota.actors.member,
      batch(quota.org.id, quota.project.id, "quota-key-001", [row("One")]),
    );
    expect(retry.replayed).toBe(false);
    expect(retry.issues).toHaveLength(1);
  });

  it("refuses the batch when the rate allowance does not cover one unit per row", async () => {
    const limited = await createTenant("importrate", "free");
    const rows = Array.from({ length: 61 }, (_, index) => row(`Row ${index}`));

    await expect(
      issueService.importIssues(
        limited.actors.member,
        batch(limited.org.id, limited.project.id, "rate-key-0001", rows),
      ),
    ).rejects.toThrow(/rate limit/i);
    await expect(issueRepo.countIssues(limited.org.id, limited.project.id)).resolves.toBe(0);
  });

  it("matches assignees case-insensitively and leaves unknown or removed addresses unassigned", async () => {
    const people = await createTenant("importpeople");
    const removed = await memberRepo.findMember(people.org.id, people.userIds.viewer);
    if (removed === null) throw new Error("fixture member missing");
    await memberRepo.archiveMember(people.org.id, removed.id);

    const result = await issueService.importIssues(
      people.actors.member,
      batch(people.org.id, people.project.id, "assignee-key-01", [
        row("Matched", { assigneeEmail: "ADMIN@importpeople.test" }),
        row("Unknown", { assigneeEmail: "nobody@elsewhere.test" }),
        row("Removed", { assigneeEmail: "viewer@importpeople.test" }),
      ]),
    );

    expect(result.issues.map((issue) => issue.assigneeId)).toEqual([
      people.userIds.admin,
      null,
      null,
    ]);
  });

  it("creates each new label once, matches existing ones exactly and never duplicates a name", async () => {
    const labelled = await createTenant("importlabels");
    await labelRepo.insertLabel({
      orgId: labelled.org.id,
      name: "Bug",
      color: "#ff0000",
      description: null,
    });

    const result = await issueService.importIssues(
      labelled.actors.member,
      batch(labelled.org.id, labelled.project.id, "label-key-0001", [
        row("Uses existing and new", { labels: ["Bug", "bug", "bug"] }),
        row("Reuses new", { labels: ["bug"] }),
      ]),
    );

    const names = (await labelRepo.listLabels(labelled.org.id)).map((label) => label.name);
    expect(names.filter((name) => name.toLowerCase() === "bug")).toEqual(["Bug", "bug"]);

    const newLabel = (await labelRepo.listLabels(labelled.org.id)).find(
      (label) => label.name === "bug",
    );
    expect(newLabel).toMatchObject({ color: "#94a3b8", description: null });

    expect(result.issues[0]?.labelIds).toHaveLength(2);
    expect(result.issues[1]?.labelIds).toEqual([newLabel?.id]);
  });

  it("publishes no per-issue announcements and writes one audit entry for the batch", async () => {
    const audited = await createTenant("importaudit");
