  it("refuses the whole batch past the project quota and leaves the key free", async () => {
    const quota = await createTenant("importquota", "free");
    for (let number = 1; number <= 99; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quota.org.id, quota.project.id, { title: `Seed ${number}` }),
        quota.actors.member.userId,
        number,
      );
    }

    await expect(
      issueService.importIssues(
        quota.actors.member,
        batch(quota.org.id, quota.project.id, "quota-key-001", [row("One"), row("Two")]),
      ),
    ).rejects.toThrow(/allows no more issues/);
    await expect(issueRepo.countIssues(quota.org.id, quota.project.id)).resolves.toBe(99);

    const retry = await issueService.importIssues(
      quota.actors.member,
      batch(quota.org.id, quota.project.id, "quota-key-001", [row("One")]),
    );
    expect(retry.replayed).toBe(false);
    expect(retry.issues).toHaveLength(1);
  });

  it("refuses the batch when the rate allowance does not cover one unit per row", async () => {
    const limited = await createTenant("importrate", "free");
    const rows = Array.from({ length: 61 }, (_, index) => row(`Row ${index}`));

    await expect(
      issueService.importIssues(
        limited.actors.member,
        batch(limited.org.id, limited.project.id, "rate-key-0001", rows),
      ),
    ).rejects.toThrow(/rate limit/i);
    await expect(issueRepo.countIssues(limited.org.id, limited.project.id)).resolves.toBe(0);
  });

  it("matches assignees case-insensitively and leaves unknown or removed addresses unassigned", async () => {
    const people = await createTenant("importpeople");
    const removed = await memberRepo.findMember(people.org.id, people.userIds.viewer);
    if (removed === null) throw new Error("fixture member missing");
    await memberRepo.archiveMember(people.org.id, removed.id);

    const result = await issueService.importIssues(
      people.actors.member,
      batch(people.org.id, people.project.id, "assignee-key-01", [
        row("Matched", { assigneeEmail: "ADMIN@importpeople.test" }),
        row("Unknown", { assigneeEmail: "nobody@elsewhere.test" }),
        row("Removed", { assigneeEmail: "viewer@importpeople.test" }),
      ]),
    );

    expect(result.issues.map((issue) => issue.assigneeId)).toEqual([
      people.userIds.admin,
      null,
      null,
    ]);
  });

  it("creates each new label once, matches existing ones exactly and never duplicates a name", async () => {
    const labelled = await createTenant("importlabels");
    await labelRepo.insertLabel({
      orgId: labelled.org.id,
      name: "Bug",
      color: "#ff0000",
      description: null,
    });

    const result = await issueService.importIssues(
      labelled.actors.member,
      batch(labelled.org.id, labelled.project.id, "label-key-0001", [
        row("Uses existing and new", { labels: ["Bug", "bug", "bug"] }),
        row("Reuses new", { labels: ["bug"] }),
      ]),
    );

    const names = (await labelRepo.listLabels(labelled.org.id)).map((label) => label.name);
    expect(names.filter((name) => name.toLowerCase() === "bug")).toEqual(["Bug", "bug"]);

    const newLabel = (await labelRepo.listLabels(labelled.org.id)).find(
      (label) => label.name === "bug",
    );
    expect(newLabel).toMatchObject({ color: "#94a3b8", description: null });

    expect(result.issues[0]?.labelIds).toHaveLength(2);
    expect(result.issues[1]?.labelIds).toEqual([newLabel?.id]);
  });

  it("publishes no per-issue announcements and writes one audit entry for the batch", async () => {
    const audited = await createTenant("importaudit");
    const created = capture("issue.created");
    const updated = capture("issue.updated");

    const result = await issueService.importIssues(
      audited.actors.member,
      batch(audited.org.id, audited.project.id, "audit-key-00001", [
        row("Audited one"),
        row("Audited two"),
      ]),
    );

    expect(created).toHaveLength(0);
    expect(updated).toHaveLength(0);

    const page = await activityService.listActivity(audited.actors.admin, {
      orgId: audited.org.id,
      limit: 100,
      cursor: null,
    });
    const entries = page.items.filter((event) => event.action === "issues.imported");
    expect(entries).toHaveLength(1);
    expect(entries[0]).toMatchObject({
      actorId: audited.userIds.member,
      subjectKind: "project",
      subjectId: audited.project.id,
      projectId: audited.project.id,
      metadata: { count: 2, importKey: "audit-key-00001" },
    });
    expect(result.issues).toHaveLength(2);
  });

  it("makes the imported issues searchable and moves the usage meter by their count", async () => {
    const indexed = await createTenant("importindex");
    const before = (await usageService.recomputeUsage(indexed.org.id)).issuesUsed;

    const result = await issueService.importIssues(
      indexed.actors.member,
      batch(indexed.org.id, indexed.project.id, "index-key-00001", [
        row("Zebra batch alpha"),
        row("Zebra batch beta"),
      ]),
    );

    const hits = await searchService.search(indexed.actors.member, {
      orgId: indexed.org.id,
      q: "Zebra batch",
      limit: 25,
      cursor: null,
    });
    expect(hits.items.map((hit) => hit.id)).toEqual(
      expect.arrayContaining(result.issues.map((issue) => issue.id)),
    );

    const metered = await usageService.getUsage(indexed.actors.member, indexed.org.id);
    expect(metered.issuesUsed).toBe(before + 2);
    const recounted = await usageService.recomputeUsage(indexed.org.id);
    expect(recounted.issuesUsed).toBe(metered.issuesUsed);
  });

  it("refuses a viewer, a foreign workspace, a foreign project, an unknown project and an archived one", async () => {
    const other = await createTenant("importforeign");
    const archivedProject = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Retired",
      slug: "retired",
      key: "RET",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: archivedProject.id,
      archiveIssues: false,
    });

    const rows = [row("Should not land")];
    const countBefore = await issueRepo.countIssues(tenant.org.id, tenant.project.id);

    await expect(
      issueService.importIssues(
        tenant.actors.viewer,
        batch(tenant.org.id, tenant.project.id, "refused-key-001", rows),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(other.org.id, other.project.id, "refused-key-002", rows),
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(tenant.org.id, other.project.id, "refused-key-003", rows),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(tenant.org.id, "01ARZ3NDEKTSV4RRFFQ69G5FZZ", "refused-key-004", rows),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(tenant.org.id, archivedProject.id, "refused-key-005", rows),
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(issueRepo.countIssues(tenant.org.id, tenant.project.id)).resolves.toBe(countBefore);
  });
});

